parameters.jsCode:
// One email for the whole week. Competitors come from the settings node, so a
// competitor that launched nothing still gets a line saying so.
const settings = $('Your competitors').first().json;
const lines = settings.competitors.split('\n').map((s) => s.trim()).filter(Boolean);
const rows = $input.all().map((i) => i.json);
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const day = (iso) => (iso ? new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '');
const count = (r) => (r.googleAdCountMin == null ? '' : r.googleAdCountMin === r.googleAdCountMax
  ? `${r.googleAdCountMin.toLocaleString('en-US')}` : `${r.googleAdCountMin.toLocaleString('en-US')}–${r.googleAdCountMax.toLocaleString('en-US')}`);

let total = 0;
let active = 0;
const sections = lines.map((line) => {
  const mine = rows.filter((r) => r.target === line);
  const failed = mine.find((r) => r.type === 'error');
  if (failed) {
    return `<h3 style="margin:28px 0 6px">${esc(line)}</h3><p style="color:#b3261e;margin:0">Couldn't look this one up: ${esc(failed.errorDescription)}</p>`;
  }
  const ads = mine.filter((r) => r.type === 'ad');
  if (!ads.length) {
    return `<h3 style="margin:28px 0 6px">${esc(line)}</h3><p style="color:#5b6673;margin:0">No new ads in the last ${esc(settings.newSince)}.</p>`;
  }
  total += ads.length;
  active += 1;
  const who = [...new Set(ads.map((a) => a.advertiserName).filter(Boolean))].slice(0, 3).join(', ');
  // Google keeps no picture of some image ads, so ads with one are shown first.
  const shown = [...ads.filter((a) => a.imageUrl), ...ads.filter((a) => !a.imageUrl)].slice(0, 6);
  const cards = shown.map((a) => `
    <td style="width:33%;padding:6px;vertical-align:top">
      <a href="${esc(a.adUrl)}" style="text-decoration:none;color:#17202a">
        <div style="border:1px solid #e4e7eb;border-radius:8px;overflow:hidden;background:#fff">
          ${a.imageUrl ? `<img src="${esc(a.imageUrl)}" alt="" style="display:block;width:100%;height:120px;object-fit:contain;background:#f6f7f8">` : `<div style="height:120px;background:#f6f7f8;color:#9aa3ad;font-size:12px;text-align:center;line-height:120px">no picture kept · open on Google</div>`}
          <div style="padding:8px 10px;font-size:12px;color:#5b6673">${esc(a.format)} · first shown ${day(a.firstShown)}</div>
        </div>
      </a>
    </td>`);
  const rowsHtml = [];
  for (let i = 0; i < cards.length; i += 3) rowsHtml.push(`<tr>${cards.slice(i, i + 3).join('')}</tr>`);
  const more = ads.length > 6 ? `<p style="margin:4px 6px;font-size:13px;color:#5b6673">and ${ads.length - 6} more.</p>` : '';
  return `<h3 style="margin:28px 0 2px">${esc(line)} <span style="font-weight:400;color:#5b6673">· ${ads.length} new</span></h3>
    <p style="margin:0 0 8px;font-size:13px;color:#5b6673">${esc(who)}${count(ads[0]) ? ` · Google lists ${count(ads[0])} ads in all` : ''}</p>
    <table style="width:100%;border-collapse:collapse">${rowsHtml.join('')}</table>${more}`;
});

const subject = total
  ? `Competitor ads: ${total} new in the last ${settings.newSince}, from ${active} of ${lines.length}`
  : `Competitor ads: nothing new in the last ${settings.newSince}`;
const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;color:#17202a">
  <h2 style="margin:0 0 4px">${esc(subject)}</h2>
  <p style="margin:0;color:#5b6673;font-size:13px">Ads Google first showed in the last ${esc(settings.newSince)}, from the Ads Transparency Center.</p>
  ${sections.join('\n')}
</div>`;
return [{ json: { subject, html, newAds: total } }];
